/// <summary>
/// Processes the staging table records to the target
/// </summary>
/// <param name = "_definitionGroupName">The name of the DMF definition group</param>
/// <param name = "_executionId">The DMF executionId</param>
/// <param name = "_entityName">The name of the entity</param>
/// <param name = "_inboundMessage">The inbound message</param>
public void processToTarget(DMFDefinitionGroupName  _definitionGroupName,
                            DMFExecutionId          _executionId,
                            DMFEntityName           _entityName,
                            OMGInboundMessageTable  _inboundMessage)
{
    DMFDefinitionGroupExecution     dMFDefinitionGroupExecution;
    DMFEntityWriter                 dMFEntityWriter;
    DMFExecution                    dMFExecution    = DMFExecution::find(_executionId);
    ;

    if (!dMFExecution)
    {
        throw Error(strFmt("@OMG:DMFExecutionNotFound", _executionId));
    }

    ttsbegin;

    dMFDefinitionGroupExecution = DMFDefinitionGroupExecution::find(_definitionGroupName, _entityName, _executionId, true);

    if (!dMFDefinitionGroupExecution)
    {
        throw Error ("@OMG:DMFDataProjectExecutionNotFound");
    }

    dMFDefinitionGroupExecution.IsSelected = NoYes::Yes;
    dMFDefinitionGroupExecution.update();

    ttscommit;


    dMFEntityWriter = new DMFEntityWriter();
    dMFEntityWriter.parmDMFExecution(dMFExecution);
    dMFEntityWriter.saveLast();

    dMFEntityWriter.runOperation(); 
}

