public void postTargetProcessing(DMFDefinitionGroupName  _definitionGroupName,
                                 DMFExecutionId          _executionId,
                                 DMFEntityName           _entityName,
                                 OMGInboundMessageTable  _inboundMessage)
{
    // Extension point for custom code
}

/// <summary>
/// Description of class
/// </summary>
/// <returns>The description</returns>
public static Description description()
{
    return "@OMG:DMFProcessing";
}

public boolean validateMessageTypeParameters(OMGMessageTypeTable  _messageTypeTable)                                                 
{                
    boolean     ret = true;
    ;

    parameterContract = FormJsonSerializer::deserializeObject(this.dataContractClass(), _messageTypeTable.InboundSerializedHandlerContract) as OMGInboundHandlerDataContract_DMF;

    if (!parameterContract)
    {
        ret = checkFailed("@OMG:DeserializeParameterError");
    }
    else if (!parameterContract.validate())
    {            
        ret = checkFailed(OMGFeatures::getErrorStr());
    }

    return ret;
}
